const $=id=>document.getElementById(id),canvas=$('world'),ctx=canvas.getContext('2d',{alpha:false});
let net=null,remotePlayers=[],furnishing=null,netErrorAt=0;
const SAVE='blsugu-survival-v1';let game=new Survival(732061),started=false,paused=false,dialogMode='',selected=null,mouse=null,view={w:0,h:0,scale:1,x:0,y:0},keys={},joy={x:0,y:0},touch={attack:false,interact:false,sprint:false};
let tick=0,last=performance.now(),hudTick=0,saveTick=0,toastTimer=0,lastMessage='',winShown=false,deathShown=false,sound=true,audio=null,saveFailed=false,dialogFocus=null;
