function portrait(){return innerHeight>innerWidth&&innerWidth<=900;}
function resize(){let d=Math.min(devicePixelRatio||1,2);canvas.width=Math.round(innerWidth*d);canvas.height=Math.round(innerHeight*d);view.w=innerWidth;view.h=innerHeight;view.scale=clamp(innerHeight/750,.68,1.35);ctx.setTransform(d,0,0,d,0,0);}
window.addEventListener('resize',resize);resize();
function toast(s){lastMessage=s;$('toast').textContent=s;$('toast').classList.add('show');toastTimer=3.8;}
function beep(f=350,t=.08,type='sine',v=.04){if(!sound||!audio)return;try{let o=audio.createOscillator(),g=audio.createGain();o.type=type;o.frequency.setValueAtTime(f,audio.currentTime);o.frequency.exponentialRampToValueAtTime(f*.65,audio.currentTime+t);g.gain.setValueAtTime(v,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+t);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+t);}catch{}}
function unlock(){try{audio=audio||new(window.AudioContext||window.webkitAudioContext)();audio.resume();}catch{}}
function readSaved(){try{return localStorage.getItem(SAVE);}catch{return null;}}
function save(manual=false){if(net){if(manual)toast('협동 기록은 서버가 자동 저장합니다.');return;}if(!started||game.dead)return;try{localStorage.setItem(SAVE,game.serialize());if(manual)toast('이 기기에 생존 기록을 저장했습니다.');}catch{if(!saveFailed||manual)toast('자동 저장을 사용할 수 없습니다. 메뉴에서 저장 파일을 내려받으세요.');saveFailed=true;}}
if(readSaved())$('continueBtn').classList.remove('hidden');
function start(g){game=g;furnishing=null;try{localStorage.setItem('blsugu-nickname',game.nickname);}catch{};started=true;paused=false;winShown=g.won;deathShown=false;selected=null;keys={};joy={x:0,y:0};$('start').classList.add('hidden');$('dialog').classList.add('hidden');for(let id of ['hud','mission','zone','bottom','utility'])$(id).classList.remove('hidden');if(coarse)$('touch').classList.remove('hidden');unlock();game.note('E / 채집 버튼으로 자원을 모으세요. 제작 메뉴에서 집을 지을 수 있습니다.');save();updateHUD();}
function newGame(){start(new Survival(Date.now(),$('difficulty').value,$('nickname').value));}
$('newBtn').onclick=()=>{if(readSaved()){openDialog('기록을 새로 시작할까요?','NEW EXPEDITION','<p>기존 자동 저장 기록이 새 게임으로 바뀝니다. 보관하려면 먼저 이어하기 후 메뉴에서 저장 파일을 내려받으세요.</p><div class="menuButtons"><button id="confirmNew" class="danger">새 생존 시작</button><button id="cancelNew">돌아가기</button></div>','confirm');$('confirmNew').onclick=newGame;$('cancelNew').onclick=closeDialog;}else newGame();};
$('continueBtn').onclick=()=>{try{start(Survival.load(readSaved()));}catch(e){toast(e.message);}};
function openDialog(title,kicker,html,mode){dialogFocus=document.activeElement;paused=true;keys={};touch={attack:false,interact:false,sprint:false};joy={x:0,y:0};$('stick').style.transform='';$('dialogTitle').textContent=title;$('dialogKicker').textContent=kicker;$('dialogBody').innerHTML=html;$('dialog').classList.remove('hidden');dialogMode=mode;$('closeDialog').focus();}
